<script lang="ts">
 import {onMount,onDestroy} from 'svelte';
 import {analytics,selectedDate,shift,numberText as fmt} from '../lib/analyticsApi';
 import ResponseScatter from './ResponseScatter.svelte';
 interface Row {id:string;date:string;name:string;type:string;sportGroup:string;durationSeconds:number|null;trainingLoad:number|null;rpe:number|null;nextDate:string;sameDayFatigue:{fatigue:number|null}|null;nextDayFatigue:{fatigue:number|null}|null;activitiesOnDay:number;dayCoverage:boolean}
 interface Response {rows:Row[];groups:{sport:string;label:string;activities:number;rated:number;medianRpe:number|null}[];sports:Record<string,string>;rated:number;total:number;coveredDays?:number;expectedDays?:number;note:string}
 let open=$state(false),date=$state(''),span=$state('28'),sport=$state(''),data=$state<Response|null>(null),busy=$state(false),error=$state('');let controller:AbortController|undefined;
 async function load(){controller?.abort();const c=new AbortController();controller=c;busy=true;error='';data=null;try{const r=await analytics<Response>(`/training-response?${new URLSearchParams({start:shift(date,-Number(span)+1),end:date,...(sport?{sport}:{})})}`,c.signal);if(!c.signal.aborted)data=r}catch(e){if(!c.signal.aborted)error=e instanceof Error?e.message:'Zapisi nisu dostupni.'}finally{if(controller===c)busy=false}}
 onMount(()=>{date=selectedDate();const change=()=>{controller?.abort();date=selectedDate();data=null};document.getElementById('date')?.addEventListener('change',change);return()=>document.getElementById('date')?.removeEventListener('change',change)});
 $effect(()=>{date;span;sport;if(open&&date)void load()});onDestroy(()=>controller?.abort());
</script>
<details class="panel analytics-panel" id="training-response" ontoggle={e=>open=e.currentTarget.open}><summary><strong>Kako odgovaraš na trening?</strong></summary>
 <div class="analytics-controls"><label>Razdoblje<select bind:value={span}><option value="28">28 dana</option><option value="90">90 dana</option></select></label><label>Sport<select bind:value={sport}><option value="">Svi sportovi</option>{#each Object.entries(data?.sports??{}) as [key,label]}<option value={key}>{label}</option>{/each}</select></label><button class="btn" onclick={()=>void load()}>Osvježi zapise</button></div>
 {#if busy}<p role="status">Učitavam osobni kontekst…</p>{/if}{#if error}<p class="analytics-error" role="status">{error}</p>{/if}
 {#if data}<p>RPE je zabilježen za {data.rated}/{data.total} aktivnosti u dostupnoj arhivi.</p><p class="quiet">Potvrđena povijest aktivnosti: {data.coveredDays??'—'}/{data.expectedDays??'—'} dana. {data.note} Sauna je izdvojena iz trening sažetka.</p>
 <div class="analytics-grid">{#each data.groups as g}<article class="analytics-card"><span>{g.label}</span><strong>{g.medianRpe==null?'Premalo zapisa':`${fmt(g.medianRpe)} / 10`}</strong><p>{g.rated}/{g.activities} aktivnosti s RPE-om; za brojčani sažetak potrebno je najmanje 5.</p></article>{/each}</div>
 <ResponseScatter rows={data.rows}/>
 <div class="analytics-table"><table><thead><tr><th>Aktivnost</th><th>Trajanje / load / RPE</th><th>Umor istog dana</th><th>Umor sljedećeg dana</th></tr></thead><tbody>{#each data.rows as r}<tr><td><a href="#activity-details" onclick={()=>document.dispatchEvent(new CustomEvent('analytics:activity-select',{detail:r}))}>{r.date} · {r.name}</a><br/>{r.sportGroup} · podvrsta treninga nije potvrđena</td><td>{fmt(r.durationSeconds==null?null:r.durationSeconds/60)} min / {fmt(r.trainingLoad)} load / {fmt(r.rpe)} RPE{#if r.rpe==null}<br/><a href="#activity-details" onclick={()=>document.dispatchEvent(new CustomEvent('analytics:activity-select',{detail:r}))}>Dopuni RPE u detaljima</a>{/if}</td><td>{fmt(r.sameDayFatigue?.fatigue)} / 10<br/>{r.activitiesOnDay} aktivnosti tog dana{!r.dayCoverage?' · povijest nepotpuna':''}</td><td>{r.nextDate}<br/>{fmt(r.nextDayFatigue?.fatigue)} / 10</td></tr>{:else}<tr><td colspan="4">Nema dostupnih aktivnosti u ovom rasponu. To ne potvrđuje razdoblje bez treninga.</td></tr>{/each}</tbody></table></div>{/if}
</details>
